sys_variable_value.value:
(function (outputs, steps, params, stepResult, assertEqual) {
	var grProperty = new GlideRecord('sys_properties');
	if (grProperty.get('name', 'x_snc_mapping_cm_autoapproval')) {
		grProperty.setValue('value', 'false');
		grProperty.update();
	} // if property
	function fnGetChoiceId(sTable, sField, sValue) {
		var grChoice = new GlideRecord('sys_choice');
		grChoice.addEncodedQuery('name=' + sTable + '^element=' + sField + '^value=' + sValue + '^language=' + gs.getProperty('glide.sys.language', 'en'));
		grChoice.setLimit(1);
		grChoice.query();
		return (grChoice.next()) ? grChoice.getUniqueValue() : '';
	} // function fnGetChoiceId
	function fnGetLocationId() {
		var grLocation = new GlideRecord('cmn_location');
		grLocation.setLimit(1);
		grLocation.query();
		return (grLocation.next()) ? grLocation.getUniqueValue() : '';
	} // function fnGetLocationId
	function fnInsertMapping(oValues) {
		var grMappingCfg = new GlideRecord('x_snc_mapping_cm_mapping_config');
		grMappingCfg.initialize();
		for (var sField in oValues) {
			grMappingCfg.setValue(sField, oValues[sField]);
		} // each field
		return grMappingCfg.insert();
	} // function fnInsertMapping
	function fnReferenceMapping(sSourceValue, bReadOnly, sStatus, sTargetValue) {
		return fnInsertMapping({
			'type': 'reference',
			'choice_table': 'cmn_location',
			'target_table': 'cmn_location',
			'source_value': sSourceValue,
			'source_display_value': 'ATF ' + sSourceValue,
			'target_value': sTargetValue,
			'read_only': String(bReadOnly),
			'active': 'true',
			'apply_job_status': sStatus
		});
	} // function fnReferenceMapping
	var sLocationId = fnGetLocationId();
	fnReferenceMapping('atf_role_writable', false, 'not_started', '');
	fnReferenceMapping('atf_role_readonly', true, 'not_started', sLocationId);
	fnReferenceMapping('atf_role_approval', false, 'approval', sLocationId);
	fnReferenceMapping('atf_role_approval_2', false, 'approval', sLocationId);
	var sParentId = fnInsertMapping({
		'type': 'choice',
		'choice_table': 'alm_asset',
		'choice_field': 'install_status',
		'target_table': 'sys_choice',
		'source_value': 'atf_role_55',
		'source_display_value': 'ATF atf_role_55',
		'target_value': fnGetChoiceId('alm_asset', 'install_status', '6'),
		'read_only': 'false',
		'active': 'true',
		'apply_job_status': 'completed'
	});
	fnInsertMapping({
		'type': 'choice',
		'choice_table': 'alm_asset',
		'choice_field': 'substatus',
		'target_table': 'sys_choice',
		'source_value': 'atf_role_33',
		'source_display_value': 'ATF atf_role_33',
		'dependent_mapping': sParentId,
		'target_value': fnGetChoiceId('alm_asset', 'substatus', 'pending_disposal'),
		'read_only': 'false',
		'active': 'true',
		'apply_job_status': 'completed'
	});
	var bAutoApprovalOff = (String(gs.getProperty('x_snc_mapping_cm_autoapproval', true)) === 'false');
	stepResult.setOutputMessage('Location: ' + sLocationId + ' | Parent: ' + sParentId + ' | Auto-approval off: ' + String(bAutoApprovalOff));
	return ((sLocationId !== '') && (sParentId !== null) && (bAutoApprovalOff === true));
})(outputs, steps, params, stepResult, assertEqual);
